use std::fmt;

pub struct Point {
    x: f64,
    y: f64,
}

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

fn sum_positive(values: &[i32]) -> i32 {
    let mut total = 0;
    for v in values {
        if *v > 0 {
            total += *v;
        }
    }
    total
}
